# CSD_RATIONALE_BEGIN
# Use an adaptive multi-phase policy: free-form reasoning observes tokens directly so the model can
# open a delimiter naturally, then each delimited span is kept grammar-controlled, with completion,
# continuation count, budget pressure, and span count jointly deciding whether to extend or close.
# After an intermediate verified span, the strategy can return to reasoning and later open a final span.
# CSD_RATIONALE_END
phase = 0
span_count = 0
reason_steps = 0
answer_steps = 0
close_ready = 0
saw_milestone = 0
final_span_target = 0
next_token = eosToken
new_steps = stepsLeft

# invariant helpers.lm == lm
# invariant helpers.parser == parser
# invariant lm.ValidTokensIdsLogits()
# invariant 0 <= stepsLeft <= maxSteps
# invariant |generated| + stepsLeft <= maxSteps
# decreases stepsLeft
while stepsLeft > 0 and phase < 4:
    if phase == 0:
        if stepsLeft <= 3 and span_count == 0:
            generated, stepsLeft = helpers.AppendLeftDelimiter(generated, stepsLeft)
            phase = 1
            answer_steps = 0
            close_ready = 0
            final_span_target = 1
        else:
            next_token = eosToken
            new_steps = stepsLeft
            if stepsLeft <= 6 or saw_milestone > 0:
                next_token, new_steps = helpers.UnconstrainedBiasLeftDelimiterStep(prompt, generated, 5.0, stepsLeft)
            else:
                next_token, new_steps = helpers.UnconstrainedAllowLeftDelimiterStep(prompt, generated, stepsLeft)
            generated = generated + [next_token]
            stepsLeft = new_steps
            reason_steps = reason_steps + 1
            if next_token == LeftDelimiter or next_token == " <<":
                phase = 1
                answer_steps = 0
                close_ready = 0
                if span_count > 0 or stepsLeft <= 8:
                    final_span_target = 1
                else:
                    final_span_target = 0
            else:
                if next_token == "." or next_token == "," or next_token == ":" or next_token == ";" or next_token == "\n":
                    saw_milestone = 1
                elif next_token == "therefore" or next_token == "total" or next_token == "answer":
                    saw_milestone = 1
                elif reason_steps > 2 and stepsLeft <= 8:
                    saw_milestone = 1
    elif phase == 1 and parser.IsCompletePrefix(helpers.LongestValidSuffix(generated)):
        if helpers.CanExtendConstrained(generated) and close_ready == 0 and stepsLeft > 1:
            suffix = helpers.LongestValidSuffix(generated)
            if parser.ValidContinuationCount(suffix) > 1 and answer_steps < 4 and helpers.MinStepsToComplete(generated) < stepsLeft:
                generated, stepsLeft = helpers.AppendExtendConstrainedStep(prompt, generated, stepsLeft)
                answer_steps = answer_steps + 1
            else:
                close_ready = 1
        else:
            generated, stepsLeft = helpers.AppendRightDelimiter(generated, stepsLeft)
            span_count = span_count + 1
            saw_milestone = 0
            if final_span_target > 0 or stepsLeft <= 2:
                phase = 4
            else:
                phase = 2
    elif phase == 1 and helpers.CanConstrain(generated):
        if stepsLeft <= helpers.MinStepsToComplete(generated) + 1:
            generated, stepsLeft = helpers.AppendTopKConstrainedStep(prompt, generated, 1, stepsLeft)
        else:
            generated, stepsLeft = helpers.AppendConstrainedStep(prompt, generated, stepsLeft)
        answer_steps = answer_steps + 1
        if answer_steps >= 3:
            close_ready = 1
    elif phase == 2:
        if stepsLeft <= 4:
            generated, stepsLeft = helpers.AppendLeftDelimiter(generated, stepsLeft)
            phase = 1
            answer_steps = 0
            close_ready = 0
            final_span_target = 1
        else:
            generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
            reason_steps = reason_steps + 1
            if reason_steps > 3 or stepsLeft <= 7:
                phase = 3
    elif phase == 3:
        generated, stepsLeft = helpers.AppendLeftDelimiter(generated, stepsLeft)
        phase = 1
        answer_steps = 0
        close_ready = 0
        final_span_target = 1

